// Entry point. index.html loads the bundled build (dist/pixel-forge.js, generated by build.py)
// so the game runs by double-clicking; dev.html loads these ES modules directly (needs a server).
import { Game } from './core/Game.js';

function showFatal(err) {
  console.error(err);
  const el = document.getElementById('boot');
  if (!el) return;
  el.classList.add('boot-error');
  el.innerHTML = `
    <div class="boot-card">
      <h1>Pixel Forge could not start</h1>
      <p>${String(err && err.message ? err.message : err).replace(/[<>&]/g, '')}</p>
      <p class="muted">Try reloading the page. If it keeps failing, use a recent Chrome, Edge, Firefox or Safari.</p>
    </div>`;
}

window.addEventListener('error', (e) => {
  if (!window.__pixelForgeStarted) showFatal(e.error || e.message);
});

const game = new Game();
game.init()
  .then(() => {
    window.__pixelForgeStarted = true;
    document.getElementById('boot')?.classList.add('boot-done');
    setTimeout(() => document.getElementById('boot')?.remove(), 700);
  })
  .catch(showFatal);

// Expose for debugging from the console (not used by the game itself).
window.pixelForge = game;
